import { useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import { initLandingInteractions } from "../components/landing/landingInteractions";

export default function LandingPage() {
  const containerRef = useRef<HTMLDivElement>(null);
  const mounted = useRef(false);
  const navigate = useNavigate();

  const htmlBase64 = "";

  useEffect(() => {
    let cleanupInteractions: (() => void) | undefined;

    if (containerRef.current && !mounted.current) {
      // Inject exact original HTML
      containerRef.current.innerHTML = atob(htmlBase64);
      
      // Initialize Three.js 3D kinetic model & interactions directly from bundle
      cleanupInteractions = initLandingInteractions(containerRef.current);

      // Set demo logged in state so login is completely bypassed
      localStorage.setItem("isLoggedIn", "true");

      const navigateToApp = (e?: Event) => {
        if (e) {
          e.preventDefault();
          e.stopPropagation();
        }
        localStorage.setItem("isLoggedIn", "true");
        navigate("/app");
      };

      // Exclude demo interactive controls from triggering full navigation
      const interactiveDemoSelectors = [
        "#simulate-refactor-btn",
        "#preset-btn",
        "#copy-refactor-btn",
        "#tact-input",
        "#interactive-mic-btn",
        "#showcase-mic-btn",
        "#tact-kinetic-canvas"
      ];

      // 1. Bind click handlers to navigation buttons and links
      const clickables = containerRef.current.querySelectorAll<HTMLElement>(
        "button, a, nav a, header a, [data-path], [role='button'], .cursor-pointer"
      );
      clickables.forEach((el) => {
        if (interactiveDemoSelectors.some(sel => el.matches(sel) || el.closest(sel))) {
          return;
        }
        el.style.cursor = "pointer";
        el.onclick = navigateToApp;
      });

      // 2. Global event delegation inside container
      const handleGlobalClick = (e: MouseEvent) => {
        const target = e.target as HTMLElement | null;
        if (!target) return;

        if (interactiveDemoSelectors.some(sel => target.matches(sel) || target.closest(sel))) {
          return;
        }

        const found = target.closest<HTMLElement>(
          "button, a, nav, header, [data-path], [role='button'], .cursor-pointer"
        );
        if (found) {
          navigateToApp(e);
        }
      };

      containerRef.current.addEventListener("click", handleGlobalClick, true);

      mounted.current = true;
    }

    return () => {
      if (cleanupInteractions) {
        cleanupInteractions();
      }
    };
  }, [navigate]);

  return <div ref={containerRef} className="w-full min-h-screen" />;
}
